PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE carriers (
	id INTEGER NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	prefix VARCHAR(100), 
	name VARCHAR(150) NOT NULL, 
	mode VARCHAR(20) NOT NULL, 
	primary_provider VARCHAR(100) NOT NULL, 
	fallback_providers VARCHAR(255), 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE shipments (
	id INTEGER NOT NULL, 
	tracking_number VARCHAR(100) NOT NULL, 
	transport_mode VARCHAR(20) NOT NULL, 
	carrier_code VARCHAR(50), 
	carrier_name VARCHAR(150), 
	awb_number VARCHAR(50), 
	container_number VARCHAR(50), 
	origin VARCHAR(255), 
	destination VARCHAR(255), 
	status VARCHAR(100), 
	pieces INTEGER, 
	weight FLOAT, 
	weight_unit VARCHAR(20), 
	volume FLOAT, 
	latest_event_status VARCHAR(255), 
	latest_event_time DATETIME, 
	last_provider_used VARCHAR(100), 
	raw_response TEXT, 
	created_at DATETIME, 
	updated_at DATETIME, tenant_id INTEGER, customer_reference VARCHAR(100), active_polling_enabled BOOLEAN DEFAULT 0, last_polled_at DATETIME, origin_lat FLOAT, origin_lng FLOAT, origin_code VARCHAR(50), origin_name VARCHAR(255), destination_lat FLOAT, destination_lng FLOAT, destination_code VARCHAR(50), destination_name VARCHAR(255), mawb_obl_no VARCHAR(100), hawb_hbl_no VARCHAR(100), vessel_name VARCHAR(150), flight_no VARCHAR(50), 
	PRIMARY KEY (id)
);
CREATE TABLE tracking_events (
	id INTEGER NOT NULL, 
	shipment_id INTEGER NOT NULL, 
	station VARCHAR(255), 
	status_code VARCHAR(50), 
	status_message VARCHAR(500), 
	event_time DATETIME, 
	flight_info VARCHAR(100), 
	pieces INTEGER, 
	weight FLOAT, 
	created_at DATETIME, latitude FLOAT, longitude FLOAT, location_code VARCHAR(50), location_name VARCHAR(255), 
	PRIMARY KEY (id), 
	FOREIGN KEY(shipment_id) REFERENCES shipments (id)
);
CREATE TABLE provider_execution_logs (
	id INTEGER NOT NULL, 
	shipment_id INTEGER, 
	tracking_number VARCHAR(100) NOT NULL, 
	provider_name VARCHAR(100) NOT NULL, 
	status VARCHAR(50) NOT NULL, 
	http_status_code INTEGER, 
	error_message TEXT, 
	request_curl TEXT, 
	response TEXT, 
	latency_ms FLOAT, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(shipment_id) REFERENCES shipments (id)
);
CREATE TABLE subscription_tiers (
	id INTEGER NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	monthly_credits INTEGER NOT NULL, 
	rate_limit_rpm INTEGER NOT NULL, 
	max_api_keys INTEGER NOT NULL, 
	allow_batch BOOLEAN, 
	allow_webhooks BOOLEAN, 
	allow_custom_carriers BOOLEAN, 
	price_usd_monthly FLOAT, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE TABLE tenants (
	id INTEGER NOT NULL, 
	slug VARCHAR(100) NOT NULL, 
	name VARCHAR(200) NOT NULL, 
	tier_code VARCHAR(50) NOT NULL, 
	monthly_quota INTEGER NOT NULL, 
	current_usage INTEGER NOT NULL, 
	rate_limit_rpm INTEGER NOT NULL, 
	allow_overage BOOLEAN, 
	is_active BOOLEAN, 
	billing_cycle_start DATETIME, 
	billing_cycle_end DATETIME, 
	created_at DATETIME, 
	updated_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tier_code) REFERENCES subscription_tiers (code)
);
CREATE TABLE api_keys (
	id INTEGER NOT NULL, 
	tenant_id INTEGER NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	key_prefix VARCHAR(30) NOT NULL, 
	key_hash VARCHAR(128) NOT NULL, 
	scopes VARCHAR(255) NOT NULL, 
	rate_limit_override INTEGER, 
	is_active BOOLEAN, 
	last_used_at DATETIME, 
	expires_at DATETIME, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);
CREATE TABLE webhook_endpoints (
	id INTEGER NOT NULL, 
	tenant_id INTEGER NOT NULL, 
	target_url VARCHAR(500) NOT NULL, 
	secret_token VARCHAR(100) NOT NULL, 
	description VARCHAR(255), 
	subscribed_events VARCHAR(255) NOT NULL, 
	is_active BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);
CREATE TABLE tenant_carrier_configs (
	id INTEGER NOT NULL, 
	tenant_id INTEGER NOT NULL, 
	carrier_code VARCHAR(50) NOT NULL, 
	custom_primary_provider VARCHAR(100), 
	custom_fallback_providers VARCHAR(255), 
	custom_credentials TEXT, 
	is_active BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
);
CREATE TABLE usage_records (
	id INTEGER NOT NULL, 
	tenant_id INTEGER NOT NULL, 
	api_key_id INTEGER, 
	tracking_number VARCHAR(100) NOT NULL, 
	transport_mode VARCHAR(20) NOT NULL, 
	carrier_code VARCHAR(50), 
	credits_consumed INTEGER NOT NULL, 
	provider_used VARCHAR(100), 
	status VARCHAR(100), 
	request_ip VARCHAR(100), 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE, 
	FOREIGN KEY(api_key_id) REFERENCES api_keys (id) ON DELETE SET NULL
);
CREATE TABLE webhook_deliveries (
	id INTEGER NOT NULL, 
	endpoint_id INTEGER NOT NULL, 
	shipment_id INTEGER, 
	event_type VARCHAR(100) NOT NULL, 
	payload TEXT NOT NULL, 
	http_status INTEGER, 
	response_body TEXT, 
	attempt_number INTEGER, 
	success BOOLEAN, 
	created_at DATETIME, 
	PRIMARY KEY (id), 
	FOREIGN KEY(endpoint_id) REFERENCES webhook_endpoints (id) ON DELETE CASCADE, 
	FOREIGN KEY(shipment_id) REFERENCES shipments (id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "users" (
                        id INTEGER NOT NULL PRIMARY KEY AUTOINCREMENT,
                        tenant_id INTEGER,
                        email VARCHAR(200) NOT NULL,
                        password_hash VARCHAR(255) NOT NULL,
                        full_name VARCHAR(150),
                        role VARCHAR(50) NOT NULL DEFAULT 'ADMIN',
                        is_active BOOLEAN DEFAULT 1,
                        last_login_at DATETIME,
                        created_at DATETIME,
                        FOREIGN KEY(tenant_id) REFERENCES tenants (id) ON DELETE CASCADE
                    );
CREATE TABLE location_coordinates (
	id INTEGER NOT NULL, 
	location_type VARCHAR(20) NOT NULL, 
	code VARCHAR(50) NOT NULL, 
	display_code VARCHAR(50), 
	icao_code VARCHAR(20), 
	name VARCHAR(255) NOT NULL, 
	city VARCHAR(150), 
	country VARCHAR(150), 
	latitude FLOAT NOT NULL, 
	longitude FLOAT NOT NULL, 
	source VARCHAR(100) NOT NULL, 
	metadata_json TEXT, 
	created_at DATETIME, 
	PRIMARY KEY (id)
);
CREATE INDEX ix_carriers_prefix ON carriers (prefix);
CREATE UNIQUE INDEX ix_carriers_code ON carriers (code);
CREATE UNIQUE INDEX ix_shipments_tracking_number ON shipments (tracking_number);
CREATE UNIQUE INDEX ix_subscription_tiers_code ON subscription_tiers (code);
CREATE UNIQUE INDEX ix_tenants_slug ON tenants (slug);
CREATE INDEX ix_api_keys_tenant_id ON api_keys (tenant_id);
CREATE INDEX ix_api_keys_key_prefix ON api_keys (key_prefix);
CREATE UNIQUE INDEX ix_api_keys_key_hash ON api_keys (key_hash);
CREATE INDEX ix_webhook_endpoints_tenant_id ON webhook_endpoints (tenant_id);
CREATE INDEX ix_tenant_carrier_configs_tenant_id ON tenant_carrier_configs (tenant_id);
CREATE INDEX ix_usage_records_api_key_id ON usage_records (api_key_id);
CREATE INDEX ix_usage_records_tenant_id ON usage_records (tenant_id);
CREATE INDEX ix_webhook_deliveries_shipment_id ON webhook_deliveries (shipment_id);
CREATE INDEX ix_webhook_deliveries_endpoint_id ON webhook_deliveries (endpoint_id);
CREATE UNIQUE INDEX ix_users_email ON users (email);
CREATE INDEX ix_users_tenant_id ON users (tenant_id);
CREATE INDEX ix_location_coordinates_location_type ON location_coordinates (location_type);
CREATE INDEX ix_location_coordinates_code ON location_coordinates (code);
CREATE INDEX ix_location_coordinates_country ON location_coordinates (country);
CREATE INDEX ix_location_coordinates_city ON location_coordinates (city);
CREATE INDEX ix_location_coordinates_icao_code ON location_coordinates (icao_code);
CREATE INDEX ix_location_coordinates_name ON location_coordinates (name);
COMMIT;
